package com.renthouse.tenancy;
import com.renthouse.common.api.*;import jakarta.validation.*;import jakarta.validation.constraints.*;import java.time.LocalDate;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1") public class TenancyController{private final TenancyService s;public TenancyController(TenancyService s){this.s=s;}@PostMapping("/landlord/appointments/{appointmentId}/contracts")ApiResponse<ContractView>create(@PathVariable long appointmentId,@RequestBody @Valid Create r){return ApiResponse.ok(s.createFromAppointment(appointmentId,new TenancyService.CreateCommand(r.startDate(),r.endDate(),r.rentCent(),r.depositCent(),r.paymentDay())));}@PostMapping("/tenant/contracts/{id}/sign")ApiResponse<ContractView>sign(@PathVariable long id){return ApiResponse.ok(s.sign(id));}@PostMapping("/tenant/contracts/{id}/checkout")ApiResponse<ContractView>out(@PathVariable long id){return ApiResponse.ok(s.checkout(id));}@GetMapping("/contracts")ApiResponse<PageResponse<ContractView>>list(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.ok(s.list(page,size));}public record Create(@NotNull LocalDate startDate,@NotNull LocalDate endDate,@PositiveOrZero Integer rentCent,@PositiveOrZero Integer depositCent,@Min(1)@Max(28)int paymentDay){}}
